import{_ as t,o as s,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Days NYC 2023: SQL on Ceph","description":"","frontmatter":{"title":"Ceph Days NYC 2023: SQL on Ceph","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","分布式存储","SQLite","Rados","Ceph Manager"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_SQL_on_Ceph.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_SQL_on_Ceph.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Ceph_Days_NYC_2023_-_SQL_on_Ceph.md"};function p(n,e,a,r,_,C){return s(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph Days NYC 2023：Ceph 上的 SQL 应用</p><p><strong>主讲人：</strong> Patrick Donnelly，IBM 的 Ceph 研发人员</p><p><strong>会议内容概述：</strong> Patrick Donnelly 介绍了如何在 Ceph 上使用 SQLite，特别是通过 libsef sqlite 库将 SQLite 数据库分布式存储在 Ceph 的 RADOS 上。他详细讨论了 Ceph 管理器（Ceph Manager）如何利用 SQLite 进行持久化存储，并深入解析了实现这一功能的架构和技术细节。</p><p><strong>关键讨论点：</strong></p><ol><li><strong>Ceph 管理器架构：</strong> Ceph Manager 通过模块化设计，允许运行 Python 脚本管理集群操作，包括编排、升级、设备健康监控等。这些模块独立于 CFS、RBD 等服务。</li><li><strong>SQLite 与 Ceph 的结合：</strong> 通过 libsef sqlite，SQLite 数据库可以分布式存储在 Ceph 的 RADOS 上，无需修改应用程序代码。这通过 SQLite 的 VFS 接口实现，允许数据库文件分布在多个 OSD 上。</li><li><strong>性能优化：</strong> 讨论了性能优化建议，如增加页面大小、使用更大的缓存、避免删除数据库文件等，以减少对 RADOS 的 IO 操作。</li></ol><p><strong>决定事项：</strong></p><ul><li>Ceph Manager 已开始使用 libsef sqlite 进行数据持久化，特别是在设备健康模块中。</li><li>计划进一步优化 libsef sqlite 库，支持多读者和读取预取性能。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>继续优化 libsef sqlite 库，解决存在的 bug 和性能问题。</li><li>探索在更多 Ceph Manager 模块中使用 SQLite 进行数据持久化。</li><li>考虑未来可能将其他数据库系统（如 PostgreSQL）集成到 Ceph 中。</li></ul><p><strong>其他信息：</strong></p><ul><li>提供了详细的性能优化建议和使用指南。</li><li>讨论了未来可能的工作方向，包括支持多读者和读取预取性能。</li></ul><p><strong>会议结束：</strong> Patrick Donnelly 回答了现场提出的问题，并提供了他的联系信息和相关文档链接，以便参与者进一步了解和使用 libsef sqlite。</p><p><strong>备注：</strong></p><ul><li>会议中提到的 libsef sqlite 和其他相关技术细节可在提供的文档和博客文章中找到。</li><li>会议纪要和相关资料将在会议结束后提供给参与者。</li></ul>',15)])])}const S=t(o,[["render",p]]);export{g as __pageData,S as default};
